public bool IsPalindromeArray(ListNode? head)
{
    var vals = new List<int>();
    while (head != null)
    {
        vals.Add(head.Val);
        head = head.Next;
    }
    int left = 0, right = vals.Count - 1;
    while (left < right)
    {
        if (vals[left] != vals[right]) return false;
        left++; right--;
    }
    return true;
}

public bool IsPalindrome(ListNode? head)
{
    if (head == null || head.Next == null) return true;
    ListNode slow = head, fast = head;
    while (fast.Next != null && fast.Next.Next != null)
    {
        slow = slow.Next!;
        fast = fast.Next.Next!;
    }
    ListNode? reversed = ReverseList(slow.Next);
    slow.Next = null;
    ListNode? p1 = head, p2 = reversed;
    while (p2 != null)
    {
        if (p1.Val != p2.Val) return false;
        p1 = p1.Next;
        p2 = p2.Next;
    }
    return true;
}

private ListNode? ReverseList(ListNode? head)
{
    ListNode? prev = null;
    while (head != null)
    {
        ListNode? next = head.Next;
        head.Next = prev;
        prev = head;
        head = next;
    }
    return prev;
}
